import { readFileSync } from "node:fs";
import path from "node:path";
import type { NextConfig } from "next";

type Redirect = Awaited<ReturnType<NonNullable<NextConfig["redirects"]>>>[number];

// 301s from the old OpenCart URLs, generated by audit_maqcenter.py.
function legacyRedirects(): Redirect[] {
  const csv = readFileSync(path.join(process.cwd(), "content", "redirects.csv"), "utf8");
  return csv
    .trim()
    .split(/\r?\n/)
    .slice(1)
    .map((line) => line.split(","))
    .filter(([from, to]) => from && to && from !== to)
    .map(([from, to]) => {
      const [pathname, query] = from.split("?");
      const route = query ? new URLSearchParams(query).get("route") : null;
      return {
        source: pathname,
        destination: to,
        permanent: true,
        ...(route && { has: [{ type: "query" as const, key: "route", value: route }] }),
      };
    });
}

const nextConfig: NextConfig = {
  cacheComponents: true,
  partialPrefetching: true,
  turbopack: {
    rules: {
      "*.css": {
        loaders: ["@tailwindcss/turbopack"],
        as: "*.css",
      },
    },
  },
  images: {
    formats: ["image/webp"],
    qualities: [75, 85],
  },
  env: {
    BUILD_YEAR: String(new Date().getFullYear()),
  },
  async redirects() {
    return legacyRedirects();
  },
};

export default nextConfig;
